def execute_command(image) -> List[ImagePatch]:
    image_patch = ImagePatch(image)
    car_patches = image_patch.find("car that is not white")
    parking_space_patches = image_patch.find("parking space")

    if not car_patches or not parking_space_patches:
        return image_patch

    valid_cars = []
    for car in car_patches:
        if not any(car.overlaps_with(ps.left, ps.lower, ps.right, ps.upper) for ps in parking_space_patches):
            valid_cars.append(car)

    return valid_cars

